import java.util.Scanner;

class StepTracker
{
    String name;   // user's name
    int sw;        // total steps walked
    double cb;     // estimated calories burned
    double km;     // estimated distance in km

    void accept()
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter name: ");
        name = sc.nextLine();
        System.out.print("Enter steps walked: ");
        sw = sc.nextInt();
    }

    void calculate()
    {
        cb = sw * 0.04;
        km = sw / 1300.0;   // 1300.0 avoids integer division
    }

    void display()
    {
        System.out.println("Name: " + name);
        System.out.println("Calories burned: " + cb);
        System.out.println("Distance (km): " + km);
    }

    public static void main(String args[])
    {
        StepTracker ob = new StepTracker();
        ob.accept();
        ob.calculate();
        ob.display();
    }
}

Sample: name = Riya, steps = 2600 -> Calories burned: 104.0, Distance (km): 2.0

import java.util.Scanner;

class Designation
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        String d[] = new String[100];   // designations of 100 employees
        int i, count = 0;
        System.out.println("Enter designations of 100 employees:");
        for (i = 0; i < 100; i++)
            d[i] = sc.nextLine();
        System.out.print("Enter designation to search: ");
        String key = sc.nextLine();
        for (i = 0; i < 100; i++)
        {
            if (d[i].equalsIgnoreCase(key))
                count++;
        }
        System.out.println("Total number of employees with designation " + key + " = " + count);
    }
}

