import java.util.Scanner;

class SparseMatrix
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        int a[][] = new int[4][5];
        int i, j, zero = 0, nonZero = 0;
        System.out.println("Enter 20 elements of the 4 x 5 matrix:");
        for (i = 0; i < 4; i++)
        {
            for (j = 0; j < 5; j++)
            {
                a[i][j] = sc.nextInt();
                if (a[i][j] == 0)
                    zero++;
                else
                    nonZero++;
            }
        }
        System.out.println("Number of zero elements = " + zero);
        System.out.println("Number of non zero elements = " + nonZero);
        if (zero > nonZero)
            System.out.println("Matrix is a Sparse Matrix");
        else
            System.out.println("Matrix is not a Sparse Matrix");
    }
}

Trace on the example: zeros per row 2 + 3 + 3 + 3 = 11, non-zeros 20 - 11 = 9; 11 > 9 so "Matrix is a Sparse Matrix".

import java.util.Scanner;

class MarkNumber
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a number: ");
        int n = sc.nextInt();
        int t = n, d, sum = 0;
        while (t > 0)
        {
            d = t % 10;
            sum = sum + d * d;   // sum of squares of digits
            t = t / 10;
        }
        if (sum % 2 == 0 && sum % 10 == n % 10)
            System.out.println(n + " is a Mark number");
        else
            System.out.println(n + " is not a Mark number");
    }
}

Trace for n = 246: sum = 36 + 16 + 4 = 56; 56 is even and 56 % 10 = 6 = 246 % 10, so "246 is a Mark number".

class Overload
{
    void format()
    {
        int i, j;
        for (i = 1; i <= 5; i++)
        {
            for (j = i; j <= 5; j++)
                System.out.print(j + "  ");
            System.out.println();
        }
    }

    int format(String s)
    {
        int i, sum = 0;
        for (i = 0; i < s.length(); i++)
            sum = sum + (int) s.charAt(i);   // ASCII code of each character
        return sum;
    }

    void format(int n)
    {
        int sum = n * (n + 1) / 2;
        System.out.println("Sum of natural numbers up to " + n + " = " + sum);
    }

    public static void main(String args[])
    {
        Overload ob = new Overload();
        ob.format();
        System.out.println(ob.format("CAB"));   // 67 + 65 + 66 = 198
        ob.format(10);                          // 55
    }
}

