import java.util.Scanner;

class Symbolic
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a word: ");
        String w = sc.next().toUpperCase();
        int i, pos = -1;
        char ch;
        for (i = 0; i < w.length(); i++)
        {
            ch = w.charAt(i);
            if ("AEIOU".indexOf(ch) == -1)   // first consonant
            {
                pos = i;
                break;
            }
        }
        String sym;
        if (pos == -1)                      // word has no consonant
            sym = w + "TR";
        else
            sym = w.substring(pos) + w.substring(0, pos) + "TR";
        System.out.println("Symbolic word is " + sym);
    }
}

Trace: AIRWAYS - first consonant R at index 2 -> "RWAYS" + "AI" + "TR" = RWAYSAITR.
BEAUTY - first consonant B at index 0 -> "BEAUTY" + "" + "TR" = BEAUTYTR.
